var ttlMs = 30000;
function createAuthStatus(read, revision, now = () => performance.now()) {
  const entries = new Map;
  let currentRevision = revision();
  return async function status(providerId) {
    if (!providerId)
      return false;
    for (;; ) {
      const captured = revision();
      if (captured !== currentRevision) {
        entries.clear();
        currentRevision = captured;
      }
      let cached = entries.get(providerId);
      if (!cached || cached.expiresAt <= now()) {
        const entry = {
          expiresAt: Infinity,
          result: Promise.resolve().then(() => read(providerId))
        };
        entries.set(providerId, entry);
        entry.result = entry.result.then((configured) => {
          entry.expiresAt = now() + ttlMs;
          return configured;
        }, (error) => {
          if (entries.get(providerId) === entry)
            entries.delete(providerId);
          throw error;
        });
        cached = entry;
      }
      try {
        const configured = await cached.result;
        if (captured === revision())
          return configured;
      } catch (error) {
        if (captured === revision())
          throw error;
      }
    }
  };
}

