function createBotMemoryOperations(harness, configuration, mutate) {
  return {
    readBotMemory: async (botId) => {
      configuration.requireBot(botId);
      const document2 = await harness.snapshot(BotMemoryDocument, botId, context2);
      if (!document2)
        return emptyMemory(botId);
      return {
        botId,
        content: document2.content,
        revision: document2.revision,
        source: document2.source,
        updatedAt: document2.updatedAt
      };
    },
    saveBotMemory: (botId, expectedRevision, content) => mutate(async () => {
      configuration.requireBot(botId);
      if (Array.from(content).length > BOT_MEMORY_MAX_CHARACTERS)
        throw new Error(`Bot 记忆最多 ${BOT_MEMORY_MAX_CHARACTERS} 个字符`);
      const sanitized = redactSensitiveText(content);
      let revision = 0;
      const updatedAt = Date.now();
      await harness.commit(async (tx) => {
        const document2 = await tx.doc(BotMemoryDocument, botId, botId);
        if (document2.revision !== expectedRevision)
          throw new Error("Bot 记忆已被其他编辑更新，请重新读取后再保存。");
        revision = document2.revision + 1;
        document2.content = sanitized.content;
        document2.revision = revision;
        document2.source = "user";
        document2.updatedAt = updatedAt;
      }, context2);
      return {
        memory: {
          botId,
          content: sanitized.content,
          revision,
          source: "user",
          updatedAt
        },
        redacted: sanitized.redacted
      };
    })
  };
}

